from pathlib import Path
import numpy as np,pandas as pd,json,sqlite3
from scipy.optimize import linprog
from common import *
ROOT=Path(__file__).parent;OUT=ROOT/'outputs';DAYS=np.array([28,56,91]);TERMS=[4,8,13]
def solve(rates,capital=1000000,reserve=100000,shock=50000,fee=0,payments=(200000,250000,200000)):
 rates=np.array(rates,dtype=float);payments=np.array(payments,dtype=float)
 if len(rates)!=3 or not np.isfinite(rates).all() or capital<=0 or reserve<0 or shock<0 or fee<0 or fee>500 or np.any(payments<0):raise ValueError('Invalid inputs')
 # Variables are purchase-dollar allocations plus uninvested cash. Fee is an upfront proportional charge.
 factors=1/(1-rates/100*DAYS/360)/(1+fee/10000)
 if np.any(factors<=0) or np.any(1-rates/100*DAYS/360<=0):raise ValueError('Invalid bill price')
 # At day 14 only cash is spendable. At each later payment, maturing bills can fund that payment.
 A=np.array([[0,0,0,-1],[-factors[0],0,0,-1],[-factors[0],-factors[1],0,-1],[-factors[0],-factors[1],-factors[2],-1]])
 cumulative=shock+np.r_[0,np.cumsum(payments)];b=-(reserve+cumulative)
 result=linprog(-np.r_[factors,1],A_ub=A,b_ub=b,A_eq=[[1,1,1,1]],b_eq=[capital],bounds=(0,None),method='highs')
 if not result.success:return {'feasible':False,'reason':'No allocation meets all payment and reserve constraints.'}
 x=np.maximum(result.x,0);balances=-A@x-cumulative;end=balances[-1];base=capital-shock-sum(payments)
 return dict(feasible=True,allocations=x.tolist(),factors=factors.tolist(),balances=balances.tolist(),terminal_cash=float(end),incremental_interest=float(end-base),all_cash_terminal=float(base),constraint_slack=(balances-reserve).tolist())
def main():
 df=pd.concat([pd.read_csv(ROOT/'data/bill_2025.csv'),pd.read_csv(ROOT/'data/bill_2026.csv')]);df['date']=pd.to_datetime(df.Date);df=df[df.date<=pd.Timestamp('2026-10-30')].sort_values('date');assert not df.date.duplicated().any()
 cols=[f'{x} WEEKS BANK DISCOUNT' for x in TERMS];assert df[cols].notna().all().all();df[['date']+cols].to_csv(OUT/'observed_discount_rates.csv',index=False)
 latest=df.iloc[-1];rates=latest[cols].to_numpy(dtype=float);ref=solve(rates);assert ref['feasible']
 allocation=pd.DataFrame({'instrument':['4-week','8-week','13-week','Cash'],'purchase_dollars':ref['allocations'],'maturity_day':[28,56,91,0],'maturity_dollars':np.array(ref['allocations'])*np.r_[ref['factors'],1]});allocation.to_csv(OUT/'reference_allocation.csv',index=False)
 ledger=pd.DataFrame({'day':[14,28,56,91],'outflow':[50000,200000,250000,200000],'cash_after_outflow':ref['balances'],'reserve':100000});ledger.to_csv(OUT/'reference_ledger.csv',index=False)
 grid=[]
 for shock in [0,25000,50000,100000,150000,200000,250000]:
  for reserve in [0,50000,100000,150000,200000]:
   for fee in [0,5,10,20,40]:
    r=solve(rates,reserve=reserve,shock=shock,fee=fee);grid.append(dict(shock=shock,reserve=reserve,fee_bps=fee,feasible=r['feasible'],incremental_interest=r.get('incremental_interest'),terminal_cash=r.get('terminal_cash')))
 pd.DataFrame(grid).to_csv(OUT/'sensitivity_grid.csv',index=False)
 historical=[]
 for _,row in df.groupby(df.date.dt.to_period('M')).tail(1).iterrows():
  z=solve(row[cols].to_numpy(dtype=float));historical.append({'observation_date':row.date.date().isoformat(),'illustrative_interest':z['incremental_interest']})
 pd.DataFrame(historical).to_csv(OUT/'historical_quote_sensitivity.csv',index=False)
 con=sqlite3.connect(':memory:');allocation.to_sql('allocation',con,index=False);ledger.to_sql('ledger',con,index=False);query=(ROOT/'reconcile.sql').read_text();sql=pd.read_sql_query(query,con);sql.to_csv(OUT/'sql_reconciliation.csv',index=False);assert abs(sql.capital.iloc[0]-1000000)<1e-6;assert sql.minimum_cash.iloc[0]>=100000-1e-6
 fig,ax=plt.subplots(figsize=(10,4.8));ax.plot(df.date,df[cols[0]],label='4-week',color='#8ac8ff');ax.plot(df.date,df[cols[1]],label='8-week',color='#f8c981');ax.plot(df.date,df[cols[2]],label='13-week',color='#b5a9ed');ax.set_ylabel('Bank discount quotation (%)');ax.legend(loc='upper center',bbox_to_anchor=(.5,1.15),ncol=3,frameon=False);ax.set_title('Observed bill quotes, not a reinvestment forecast',loc='left',pad=40);savefig(OUT,'bill-rates',fig)
 fig,ax=plt.subplots(figsize=(10,4.8));ax.step([0,14,28,56,91],[ref['allocations'][3]]+ref['balances'],where='post',color='#8ac8ff');ax.scatter([14,28,56,91],ref['balances'],color='#8ac8ff');ax.axhline(100000,color='#f8c981',linestyle='--',label='Assumed reserve');ax.set(xlabel='Modeled day after purchase',ylabel='Spendable cash after payments ($)',title='A scenario ledger: each payment must clear');ax.legend(frameon=False);savefig(OUT,'cash-ledger',fig)
 finding=f"Using {latest.date.date().isoformat()} quotations, the illustrative $1 million plan earns ${ref['incremental_interest']:,.0f} above zero-yield cash while preserving a $100,000 reserve after $700,000 of scheduled and stress payments. This is a modeled bill return, not an executed trade."
 limits='Indicative secondary-market bid quotations are not executable offers. Fixed 28-, 56- and 91-day tenors stand in for actual security settlement and maturity dates. No reinvestment, early sale, bid-ask spread, taxes, lot sizes, holiday adjustment or credit facility is modeled. Cash earns zero in the baseline. Actual cash forecasts, offers and security identifiers are required before implementation. Reserve and payments are hypothetical; this is not a forecast of a real company’s cash.'
 dump(OUT/'summary.json',dict(observation_date=latest.date.date().isoformat(),discount_rates_pct=rates.tolist(),reference=ref,finding=finding,limitations=limits,quote_rows=len(df),sensitivity_cases=len(grid)))
 report='<section class="section"><h2>Payment dates come before headline yield.</h2><p>'+finding+'</p><div class="note">Observed inputs: Treasury bill quotations. Assumed inputs: $1 million capital, $100,000 reserve, $50,000 day-14 stress payment, and $200,000 / $250,000 / $200,000 at days 28 / 56 / 91.</div>'+figure(OUT,'bill-rates','Source: U.S. Treasury daily bill files for 2025 and 2026, retrieved October 30, 2026. Bank discount basis, not coupon-equivalent yields.')+'<h2>The reference allocation</h2>'+table(allocation)+figure(OUT,'cash-ledger','Hypothetical cash-flow schedule. Maturity proceeds are available before payments on the same modeled day. Interest is not reinvested.')+table(ledger)+'<h2>What the optimization does</h2><p>A linear program allocates purchase dollars to three bill tenors and cash. It maximizes terminal spendable cash, subject to capital conservation, nonnegative holdings and a minimum reserve after every payment. The baseline holds all money in zero-yield cash. A sensitivity grid changes reserves, early stress payments and upfront proportional fees.</p><p>For discount quote d and days T, price per dollar of face = 1 − dT/360. Maturity factor per allocated dollar = 1 / [(1 − dT/360)(1 + fee/10,000)]. Coupon-equivalent values are retained in raw data but never substituted into this formula.</p><h2>Decision implication</h2><p>Ask how much cash is available before each liability falls due. A higher-yielding long bill cannot fund a day-14 payment without an early sale, which this model disallows. Change the payment assumptions before interpreting the allocation.</p><p><a href="workbench.html">Test the cash schedule</a></p><details><summary>Limitations and implementation requirements</summary><p>'+limits+'</p></details><h2>Evidence</h2><p><a href="reference_allocation.csv">Allocation CSV</a> · <a href="reference_ledger.csv">Cash ledger</a> · <a href="sensitivity_grid.csv">Sensitivity grid</a> · <a href="observed_discount_rates.csv">Observed quotations</a> · <a href="sql_reconciliation.csv">Independent SQL checks</a></p><p><a href="https://home.treasury.gov/resource-center/data-chart-center/interest-rates/TextView?type=daily_treasury_bill_rates&amp;field_tdr_date_value=2026">Official Treasury source and conventions</a></p></section>'
 page(ROOT,'report.html','Which cash can wait until maturity?',finding,report)
 controls=[('capital','Capital ($)',1000000),('reserve','Minimum reserve ($)',100000),('shock','Day-14 stress payment ($)',50000),('p28','Day-28 payment ($)',200000),('p56','Day-56 payment ($)',250000),('p91','Day-91 payment ($)',200000),('fee','Upfront fee (basis points)',0)]
 form='<section class="section"><p class="note">Hypothetical planning tool using '+latest.date.date().isoformat()+' indicative quotes. Cash earns zero; no early sale or reinvestment. Security dates and executable prices must be checked separately.</p><form id="scenario"><div class="formgrid">'+''.join(f'<label for="{i}">{label}<input id="{i}" name="{i}" type="number" min="0" max="'+('500' if i=='fee' else '100000000000')+f'" step="any" value="{v}" required></label>' for i,label,v in controls)+'</div><button type="submit">Recalculate allocation</button></form><div id="results" class="results" aria-live="polite"></div><button id="download" type="button">Download scenario JSON</button><details><summary>Read the assumptions</summary><p>'+limits+'</p><p>Day-14 stress cash is held from the start and is an additional outflow, not a probability-weighted loss. Fees are paid upfront as a percentage of each bill allocation, not an annual expense ratio. Maturity receipts precede same-day payments. The solver checks every payment date.</p></details><p><a href="report.html">Read the evidence and formulation</a></p></section>'
 page(ROOT,'workbench.html','Earn yield without missing the payment.', 'Move the cash requirements. See which maturities still fit.',form,(OUT/'calculator.js').read_text(),dict(rates=rates.tolist(),date=latest.date.date().isoformat()))
 (ROOT/'docs/executive_memo.md').write_text('# Decision memo\n\n'+finding+'\n\nAllocate against payment dates rather than headline yield. The reference linear program is feasible at every modeled payment date. Re-run with a company-approved cash forecast and executable security details before any treasury action.\n\n## Limits\n'+limits+'\n')
 print(finding)
if __name__=='__main__':main()
